/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program works with an undirected graph
 * whose vertices are the integers 0 … 7.  Edges are supplied on the
 * command line as a list of integer pairs:
 *
 *     prog55_connected_components u1 v1 u2 v2 … uk vk
 *
 * The number of arguments after the program name must be even; otherwise
 * the program prints “INVALID_INPUT” and exits (return value 0, matching
 * the original binary).
 *
 * For each pair (ui,vi) the program checks that both numbers are in the
 * range [0,7]; if any number is out of range the same error message is
 * printed.
 *
 * After the graph is built the program computes the connected components
 * using a breadth‑first search.  The components are printed in the order
 * in which the smallest vertex of each component is discovered (i.e. in
 * increasing vertex number).  Within a component the vertices are printed
 * in the order they are visited by the BFS.
 *
 * Output format (one line per component):
 *
 *     <component_index>: {v0,v1,…,vn}
 *
 * where <component_index> starts at 0.  A newline follows each line.
 *
 * The program never uses dynamic allocation and works entirely with
 * fixed‑size arrays because the vertex set is limited to eight nodes.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8                     /* vertices are 0 … 7 */

int main(int argc, char **argv)
{
    /* -----------------------------------------------------------------
       1.  Validate the command‑line arguments.
       ----------------------------------------------------------------- */
    if ( ((argc - 1) & 1) != 0 ) {          /* odd number of arguments after prog name */
        puts("INVALID_INPUT");
        return 0;                           /* original binary returns 0 */
    }

    /* -----------------------------------------------------------------
       2.  Build the adjacency matrix.
       ----------------------------------------------------------------- */
    int adj[MAXV][MAXV] = { {0} };

    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long a = strtol(argv[i],     &endptr, 10);
        if (*endptr != '\0' || a < 0 || a >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }
        long b = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0' || b < 0 || b >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[(int)a][(int)b] = 1;
        adj[(int)b][(int)a] = 1;            /* undirected */
    }

    /* -----------------------------------------------------------------
       3.  Find and print the connected components.
       ----------------------------------------------------------------- */
    bool visited[MAXV] = { false };
    int  component = 0;

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;

        /* ---- BFS queue (max size = MAXV) ---- */
        int  queue[MAXV];
        int  qhead = 0, qtail = 0;
        int  comp_nodes[MAXV];
        int  comp_len = 0;

        visited[start] = true;
        queue[qtail++] = start;

        while (qhead < qtail) {
            int v = queue[qhead++];
            comp_nodes[comp_len++] = v;

            for (int w = 0; w < MAXV; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = true;
                    queue[qtail++] = w;
                }
            }
        }

        /* ---- Print this component ---- */
        printf("%d:", component);
        printf(" {");
        for (int i = 0; i < comp_len; ++i) {
            printf("%d", comp_nodes[i]);
            if (i + 1 < comp_len)
                putchar(',');
        }
        putchar('}');
        putchar('\n');

        ++component;
    }

    return 0;
}
